async function run(){await db.initialize();console.log("Database initialized.");const e=db.models.exchange;if(e){const o=await e.findAll();console.log("Exchanges count:",o.length);for(const e of o)console.log(`- Name: ${e.name}, Title: ${e.title}, Status: ${e.status}`)}else console.error("Exchange model not found!");process.exit(0)}require("dotenv").config({path:"../.env"});require("./module-alias-setup.js");const{db:db}=require("@b/db");run().catch(e=>{console.error(e);process.exit(1)});